/bin/bash -lc "python3 - <<'PY'
import io
import json
import urllib.request
from openai_client import OpenAIClient

class FakeResponse(io.BytesIO):
    def __enter__(self):
        return self
    def __exit__(self, *args):
        return False

captured = {}

def fake_urlopen(request, timeout):
    captured[\"url\"] = request.full_url
    captured[\"payload\"] = json.loads(request.data.decode())
    return FakeResponse(json.dumps({
        \"output\": [{
            \"type\": \"message\",
            \"content\": [{\"type\": \"output_text\", \"text\": \"ok\"}],
        }]
    }).encode())

urllib.request.urlopen = fake_urlopen
client = OpenAIClient(api_key=\"test\", base_url=\"http://example.invalid/v1\")
result = client.send_text_prompt(\"private prompt\")
assert result == \"ok\", result
assert captured[\"payload\"] == {\"input\": \"private prompt\", \"model\": \"gpt-5-mini\", \"store\": False}
print(\"offline check passed\")
PY"

